import json,html
from pathlib import Path
p=Path('website/content/home.json');d=json.loads(p.read_text(encoding='utf-8'));h=d['html']
if 'id="payam-product-details"' in h:raise SystemExit('Product details already present')
e=lambda s:html.escape(s,quote=True)
category=[('Payments','Airtime, data, electricity and other supported bills.'),('Food','Explore meals through available restaurant partners.'),('Shopping','Browse local products and review the details before ordering.'),('Grocery','Foodstuffs and household essentials from local sellers.'),('Transport','Explore available partner transport options.'),('Services','Cleaning, repairs and help with everyday tasks.'),('Health','Explore products and services from available health providers.'),('Business','Printing, creative work and professional support.')]
def cards(items):return '<div class="payam-detail-grid">'+''.join('<article class="payam-detail-card"><h3 class="typo-h3 text-ds-text-black">'+e(title)+'</h3><p class="typo-d2 text-ds-text-muted">'+e(text)+'</p></article>' for title,text in items)+'</div>'
def section(id,label,title,body):return '<section id="'+id+'" class="w-full bg-ds-bg-off payam-detail-section"><div class="payam-detail-container"><span class="payam-detail-label text-ds-brand-emerald">'+e(label)+'</span><h2 class="typo-h2 text-ds-text-black">'+e(title)+'</h2>'+body+'</div></section>'
blocks=section('payam-product-details','Explore Payam','Eight categories. One everyday companion.',cards(category)+'<p class="payam-detail-note text-ds-text-muted">Available products, services and partner options depend on your location.</p>')
blocks+=section('payam-money-tools','Money tools','For the payments you coordinate together.',cards([('SplitPay','Coordinate a shared payment. Review who is involved, each share and the payment status.'),('Pay4Me','Ask someone to pay for you through a supported Pay4Me request. Check the details before confirming.'),('Money requests','Send a money request and follow its status in the app.')])+'<p class="payam-detail-note text-ds-text-muted">Review the recipients, amounts, fees and status for the tool you choose.</p>')
blocks+=section('payam-for-someone-else','For you or someone else','Sometimes, the person you are helping is elsewhere.',cards([('Pay a bill for someone','Use their mobile number, meter or account details in a supported payment journey.'),('Buy for another person','Where the journey supports it, provide the recipient and fulfilment details for the order.'),('Request help at their location','Describe the task and provide the relevant contact and location details in a supported service request.')])+'<p class="payam-detail-note text-ds-text-muted">Check the recipient’s details and permission before confirming.</p>')
blocks+=section('payam-business-details','Payam for Business','Make what you do easier to find.',cards([('Present your offering','Publish products or services with clear photos, descriptions, scope and pricing.'),('Keep the details current','Update your availability, service area and delivery or pickup information.'),('Manage customer work','Review incoming orders and requests, clarify requirements and follow the next step.')])+'<a href="/business" class="payam-detail-link text-ds-brand-emerald">More about Payam for Business →</a>')
steps=[('1. Find a provider','Explore the relevant service and review what the provider offers.'),('2. Describe the task','Share the problem, location and preferred timing. Add useful details where supported.'),('3. Review the quote','Check the scope, price and schedule before accepting. Confirm what is included.'),('4. Follow the work','Keep track of the request and agreed details in the app. Use Help if you need support.')]
blocks+=section('payam-service-journey','A service journey','Need help with cleaning or a repair?',cards(steps)+'<p class="payam-detail-note text-ds-text-muted">The steps available depend on the service and provider. A request does not mean the work has been accepted or paid for.</p>')
questions=[('Is everything available in my area?','Availability depends on your location, participating sellers, providers and partners. Check the options shown in the app.'),('Where can I see charges?','Review the price, applicable fees and total before confirming. Service work may need an agreed quote.'),('What if a payment is still processing?','Check its status before trying again. Keep the transaction reference and contact support if you need help.'),('What should I check in a service quote?','Read the scope, price, timing and any materials or other charges. Clarify anything missing before accepting.'),('How do I get help with an order or request?','Use Help in the app or email support@payam.ng with the relevant reference. Never share your password or transaction PIN.')]
faq='<div class="payam-detail-faq">'+''.join('<details><summary class="text-ds-text-black">'+e(q)+'</summary><p class="text-ds-text-muted">'+e(a)+'</p></details>' for q,a in questions)+'</div>'
blocks+=section('payam-practical-faq','Practical answers','A little clarity before your next step.',faq)
marker='<section id="how-it-works"';assert marker in h
h=h.replace(marker,blocks+marker,1);d['html']=h;p.write_text(json.dumps(d,ensure_ascii=False),encoding='utf-8')
print('Added six product detail sections. Existing page markup and images retained.')
